-- GENERATED by `wfj generate` from data/gossip/gossip-fd.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["fd0c2d35d227bfdb"] = { "Noi aiutare te trovare loro.", "." },
  ["fd0ffedcfa5633b6"] = { "Ti servono indicazioni, <ragazzo/ragazza>?", "." },
  ["fd161a9ab8913845"] = { "La casa d'aste di Orgrimmar è nella ⟦Valley of Strength=Valle della Forza⟧. Cercala sul lato est, accanto a Boomstick Imports.", "." },
  ["fd17ecc6baa6a85e"] = { "Non ci posso credere... Stavo facendo una normale ricognizione sopra la zona smilitarizzata centrale quando è scoppiato l'inferno. Ho visto il comandante di stormo dell'⟦Horde=Orda⟧, Mulverick, abbattere sia Ichman sia Slidore! La rabbia ha preso il sopravvento: ho lasciato il mio gregario e ho buttato giù quel bastardo di Mulverick. Purtroppo, prima di schiantarsi, ha colpito il mio grifone, costringendo a terra anche me. E alla fine questi selvaggi mi hanno catturato.\n\nDevo tornare alla base! Aiuto!", "." },
  ["fd18c75c3330d52d"] = { "Sì, qualcosa la sai! Se vuoi imparare di più, dovrai parlare con Georgio Bolero a ⟦Stormwind=Roccavento⟧.", "." },
  ["fd22ca5c608a2f6a"] = { "Volevo chiederti di quella scimmia.", "." },
  ["fd2492c890549760"] = { "La tua ricerca per imparare il draconico è inutile, mortale. E perché mai vorresti imparare a parlare la lingua antica? Davvero sconcertante...", "." },
  ["fd28d4d3e5978216"] = { "GOOOOOOOOOOOOOOL!", "." },
  ["fd2d84b78c97240d"] = { "La Dama Oscura ha detto che la conoscenza sarà la nostra arma più grande in questa guerra.", "." },
  ["fd393927f0ce4f24"] = { "È come si dice: tale padre, tale figlio. Hai la volontà debole quanto Tirion... forse di più. Posso solo sperare che i miei assassini siano finalmente riusciti a mettere fine alla sua vita pietosa.", "." },
  ["fd3ac19926d03690"] = { "Meno di cento di noi, contro più di mille orchi. Solo una manciata di noi è riuscita ad andarsene da lì.", "." },
  ["fd3c567963a299f3"] = { "Ma se lo spostamento di frequenza risultante mandasse un contraccolpo magico su per i flussi?", "." },
  ["fd3d57b8cc47cf74"] = { "%s si attiverà tra 10 secondi!", "." },
  ["fd3d5be2c54f89ff"] = { "Non vali niente, Ribbly. È ora di pagare per la tua malvagità!", "." },
  ["fd49e921d8ec5aae"] = { "Chi controlla il ⟦Stonehearth Bunker=Fortilizio di Cordipietra⟧?", "." },
  ["fd4c127dab4f13a3"] = { "Perché il nostro popolo sopravviva, dobbiamo studiare le vie della natura e apprenderne i segreti.", "." },
  ["fd4f2ee463dfd54c"] = { "Ah, cerchi il chierico oscuro Beryl. È al piano di sopra, nella sala di lettura della ⟦Gallows' End Tavern=Taverna dell'Impiccato⟧. Legge, prega, chissà cosa combina... e chi oserebbe chiederglielo?", "." },
  ["fd518631c1b3ea21"] = { "Ah, che sfortuna! Le mie capacità non bastano per esserti utili. Pazienza. Parla con ⟦Fimble Finespindle=Fimble Filofino⟧, laggiù vicino al telaio. Lavora il cuoio da più tempo di me.", "." },
  ["fd5702fdd5dfaaec"] = { "Spero che tu non sia venut<o/a> fino alla ⟦Great Forge=Grande Forgia⟧ solo per stare al caldo. Parla, <ragazzo/ragazza>: cosa posso fare per te?", "." },
  ["fd705848a68cd3cd"] = { "Non ci sconfiggerete mai!", "." },
  ["fd70a77ce8af287c"] = { "È saggio che tu ti umili davanti a me, {name}, nel tuo desiderio di altro sapere da stregone.", "." },
  ["fd717f2660e2b0a6"] = { "Questo è il posto, {race}: la ⟦The Cauldron=Caldera Magmatica⟧! Segnalo su una mappa o fai qualcosa per non dimenticartelo. Se mi succedesse qualcosa, la mia squadra resterebbe bloccata in quella miniera per sempre.", "." },
  ["fd751c2bf9554986"] = { "È fatta! Il magistrato è morto... nell'ombra, fratelli miei.", "." },
  ["fd774fb02234081d"] = { "In base al campione di tossina che ci hai fornito, pensiamo che ti servirà quanto segue: un Accelerante Arcano, sei Agitatori Ossei e quattro pezzi di Telarunica. Con il Focalizzatore Vitreo al seguito, procurati gli agitatori dai non morti scheletrici qui nelle ⟦Plaguelands=Terre Infette⟧!\n\nQuando avrai questi oggetti, dovresti riuscire a caricare l'antidoto in quel calderone.", "." },
  ["fd80664028c1a960"] = { "Aiuto!", "." },
  ["fd8dc59ff1b5bb73"] = { "E verso quale campo di battaglia desideri viaggiare?", "." },
  ["fd9302c9d50f70d0"] = { "Ho sofferto, ma ora lo sento svanire piano da me. Sento... la libertà.", "." },
  ["fd95af2efdfcaacd"] = { "10 secondi all'esplosione! State indietro!!!", "." },
  ["fd9a0f74668fcdc5"] = { "L'antico Altar of Hakkar si erge silenzioso vicino all'ingresso della sala.\n\nGuardando le balconate sopra di esso, noti che su ognuna poggia una grande statua a forma di serpente. Le statue somigliano molto a quelle sull'altare davanti a te. Devono essere collegate in qualche modo...", "." },
  ["fd9d5e50940e7af9"] = { "Seikwa può prendersi cura dei tuoi amici animali quando ne hai bisogno. Cercala davanti alla locanda.", "." },
  ["fd9e1ed9ad056e24"] = { "Nel tempo prima del tempo, in quella che gli usurpatori avrebbero poi chiamato la Prima Era della Creazione, il mio padrone e i suoi fratelli dominavano questo mondo. Furono loro, gli Dei Antichi, a creare ogni cosa.\n\nE furono loro a essere infine abbattuti da coloro che si sarebbero fatti chiamare Plasmatori.", "." },
  ["fd9f444bf7364ef4"] = { "Hai già parlato con uno dei miei accoliti dentro la torre, {name}? Non possiamo completare il tuo globo finché non avrai svolto uno dei loro compiti. Parla con loro adesso, se sei <pronto/pronta>.", "." },
  ["fda40828771eabfe"] = { "I tauren sono figli e figlie della Madre Terra, e mostriamo rispetto per tutti i suoi figli. Anche le bestie che uccidiamo sono care, perché i loro corpi ci nutrono e le loro pelli ci danno calore.", "." },
  ["fdaad78e10cd3efc"] = { "%s si lancia in una furia omicida!", "." },
  ["fdbffd594571ac01"] = { "Questi sono tempi pericolosi, {race}. Un male antico si sta risvegliando, e non gli importa se sei dell'⟦Horde=Orda⟧ o dell'⟦Alliance=Alleanza⟧.", "." },
  ["fdc153acaba887a0"] = { "Non manca molto. La strada principale è proprio qui avanti.", "." },
  ["fdc42f2a194fa8d5"] = { "Temo che il tuo quoziente di oscurità non sia sufficiente perché io mi prenda il disturbo di parlarti ancora. Circolare, prego.", "." },
  ["fdc7aae907c04ff4"] = { "Sayoc è il maestro d'armi orco e si trova nella ⟦Valley of Honor=Valle dell'Onore⟧ di Orgrimmar. Insegna l'uso di archi, pugnali, tirapugni, asce a una e a due mani e armi da lancio.\n\nHanashi, la maestra d'armi troll nella ⟦Valley of Honor=Valle dell'Onore⟧ di Orgrimmar, può insegnare l'uso di archi, asce a una e a due mani, bastoni e armi da lancio.\n\nArchibald, il maestro d'armi non morto nel ⟦War Quarter=Quartiere della Guerra⟧ di ⟦Undercity=Sepulcra⟧, può addestrare all'uso di balestre, pugnali, spade a una e a due mani e armi ad asta.", "." },
  ["fdc88a1b1b7e4a14"] = { "Non ci posso credere che papà non mi lasci tenere tua sorella.", "." },
  ["fdc8f76276596691"] = { "Un pesciolino? Gli oceani sono pieni di pesciolini! Là fuori potrebbero essercene cento milioni!", "." },
  ["fdcd1273237b5d84"] = { "Non abbiamo ancora raggiunto la quota di legname richiesta. Ora torna al lavoro.", "." },
  ["fdce4dc2b7a8d3de"] = { "Con i calderoni violati, ora possiamo introdurre l'agente neutralizzante nell'ambiente. Questo dovrebbe ripagare il Flagello con la sua stessa moneta, per così dire!\n\nRivolgiti allo speziale Dithers per le informazioni sui reagenti da usare nei calderoni. Io mi occuperò di tutti i rapporti su come stiamo procedendo nel complesso per rivoltare la piaga contro il Flagello!", "." },
  ["fdd07cae60c4065b"] = { "Maestro, dove sono finiti tutti gli alberi?", "." },
  ["fde081abdaa6cb63"] = { "Avete combattuto tutti con forza e valore. Mi riempie d'orgoglio vedere i guerrieri che siete diventati.", "." },
  ["fde1d7c619c766f6"] = { "Sono perduti, {race}. Libram scritti dai maestri elfici. Sparsi per il mondo quando il Flagello fu scatenato su Quel'Thalas.\n\nOra cerchiamo questi libram. Li cerchiamo per scoprire i segreti che custodiscono, per ripristinare il potere di un tempo.\n\nIo cerco i dieci scritti dal maestro Kariel Winthalus. Se trovi un libram, permettimi di assorbirne le proprietà magiche e forgerò per te un amalgama di potere... naturalmente, tutto ha un prezzo. Troverai il mio prezzo alto; ma lo pagherai.", "." },
  ["fded3f36e6214cd5"] = { "Che tempismo perfetto, {class}.\n\nMi chiamo Lotwil Veriatus, membro fondatore della Enlightened Assembly of Arcanology, Alchemy, and Engineering Sciences: cerchiamo di fondere le scienze intellettuali di Azeroth in un'unica scuola onnicomprensiva.", "." },
  ["fdfbfd41ac8c7fc2"] = { "Grazie, grande spirito. Grazie!", "." },
  ["fdfeab55d2128c9f"] = { "Anaya...? I miei occhi mi ingannano? Sei davvero tu?", "." },
})
